<?php
declare(strict_types=1);
require dirname(__DIR__).'/app/bootstrap.php';
$admin=require_admin($pdo);$success='';$error='';
if(!commercial_promotions_ready($pdo)){http_response_code(503);exit('Coupons, Promotions & Credits requires migration 071.');}
if($_SERVER['REQUEST_METHOD']==='POST'){require_csrf();try{
    $op=(string)($_POST['op']??'');
    if($op==='create'){commercial_promotion_create($pdo,$admin,$_POST);$success='Promotion created.';}
    elseif($op==='update'){commercial_promotion_update($pdo,$admin,(string)($_POST['promotion_id']??''),$_POST);$success='Promotion updated.';}
    elseif($op==='sync'){ $p=commercial_promotion($pdo,(string)($_POST['promotion_id']??''));if(!$p)throw new RuntimeException('Promotion not found.');commercial_promotion_sync_stripe($pdo,$config,$admin,$p);$success='Promotion synchronized to Stripe.'; }
    elseif($op==='credit'){ $amount=(int)round(((float)($_POST['amount_dollars']??0))*100);commercial_credit_adjust($pdo,$config,$admin,(string)($_POST['account_id']??''),(string)($_POST['direction']??'credit'),$amount,(string)($_POST['reason']??''));$success='Customer credit balance adjustment applied.'; }
    elseif($op==='reverse_credit'){commercial_credit_reverse($pdo,$config,$admin,(string)($_POST['adjustment_id']??''),(string)($_POST['reason']??'Reversal of prior adjustment.'));$success='Credit adjustment reversed.';}
    elseif($op==='retry_credit'){commercial_credit_retry_public($pdo,$config,$admin,(string)($_POST['adjustment_id']??''));$success='Credit adjustment retried successfully.';}
    else throw new RuntimeException('Unknown promotions action.');
}catch(Throwable $e){$error=$e->getMessage();}}
$mode=(string)(stripe_billing_settings($pdo)['mode']??'test');$promotions=commercial_promotions_list($pdo);$packages=subscription_packages($pdo,false);
$accounts=$pdo->query("SELECT a.public_id,a.name,p.name package_name FROM accounts a JOIN subscription_packages p ON p.id=a.package_id WHERE a.status<>'closed' ORDER BY a.name,a.id")->fetchAll()?:[];
$redemptions=commercial_recent_redemptions($pdo,100);$discounts=commercial_recent_discount_events($pdo,100);$credits=commercial_recent_credits($pdo,100);$revenue=commercial_revenue_adjustment_summary($pdo,30);
$money=fn(int $c)=>'$'.number_format($c/100,2);$dt=fn(?string $v)=>$v?str_replace(' ','T',substr($v,0,16)):'';
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Promotions & Credits · Annotated Admin</title><link rel="stylesheet" href="/assets/css/app.css"></head><body><?=admin_ui_sidebar('promotions')?>
<main class="panel adminPromotionsPage"><div class="pageTitle"><span class="eyebrow">ADMIN V1.80</span><h1>Coupons, promotions & credits</h1><p>Annotated owns eligibility, redemption, credits and audit history. Stripe mirrors the validated discount or customer credit adjustment in the active <?=h($mode)?> environment.</p></div>
<?php if($success):?><div class="success"><?=h($success)?></div><?php endif?><?php if($error):?><div class="error"><?=h($error)?></div><?php endif?>
<section class="billingKpiGrid"><article class="card"><span class="meta">Active promotions</span><strong><?=h((string)count(array_filter($promotions,fn($p)=>$p['status']==='active')))?></strong></article><article class="card"><span class="meta">Discounts · 30d</span><strong><?=h($money((int)$revenue['discount_cents']))?></strong></article><article class="card"><span class="meta">Credits issued · 30d</span><strong><?=h($money((int)$revenue['credit_issued_cents']))?></strong></article><article class="card"><span class="meta">Net discounted invoice total · 30d</span><strong><?=h($money((int)$revenue['net_cents']))?></strong></article></section>

<details class="card" open><summary><strong>+ Create promotion</strong></summary><form method="post" class="stack"><?=csrf_field()?><input type="hidden" name="op" value="create">
<div class="adminPackageFields"><label>Name<input name="name" required></label><label>Code<input name="code" required maxlength="40" placeholder="WELCOME25"></label><label>Status<select name="status"><option value="draft">Draft</option><option value="active">Active</option></select></label><label>Discount type<select name="discount_type"><option value="percent">Percent</option><option value="fixed_amount">Fixed amount</option></select></label><label>Percent off<input name="percent_off" inputmode="decimal" placeholder="25"></label><label>Fixed amount ($)<input name="amount_off_dollars" inputmode="decimal" placeholder="10.00"></label><label>Duration<select name="duration"><option value="once">Once</option><option value="repeating">Repeating</option><option value="forever">Forever</option></select></label><label>Repeating months<input name="duration_months" type="number" min="1" max="60" value="1"></label><label>Customer scope<select name="customer_scope"><option value="all">All customers</option><option value="new_customers">New customers</option><option value="existing_customers">Existing customers</option></select></label><label>Minimum package ($)<input name="minimum_package_dollars" inputmode="decimal"></label><label>Starts<input type="datetime-local" name="starts_at"></label><label>Ends<input type="datetime-local" name="ends_at"></label><label>Global redemptions<input type="number" name="max_redemptions" min="1" placeholder="Unlimited"></label><label>Per-account limit<input type="number" name="per_account_limit" min="1" max="100" value="1"></label></div>
<label>Description<textarea name="description" rows="2"></textarea></label><fieldset><legend>Eligible packages</legend><p class="meta">Leave every package unchecked to allow all packages.</p><?php foreach($packages as $pkg):?><label><input type="checkbox" name="package_ids[]" value="<?=h((string)$pkg['public_id'])?>"> <?=h((string)$pkg['name'])?></label><?php endforeach?></fieldset><button>Create promotion</button></form></details>

<section class="card"><div class="sectionHeadWeb"><div><span class="eyebrow">PROMOTION CATALOG</span><h2>Governed offers</h2></div><span class="badge"><?=h($mode)?> Stripe</span></div>
<?php foreach($promotions as $p):$eligible=array_map('intval',json_decode((string)($p['eligible_package_ids_json']??'[]'),true)?:[]);$mapping=commercial_promotion_mapping($pdo,(int)$p['id'],$mode);?><details class="historyItem"><summary><strong><?=h((string)$p['code'])?> · <?=h((string)$p['name'])?></strong> <span class="meta"><?=h((string)$p['status'])?> · <?=h((string)$p['applied_redemptions'])?> applied · Stripe <?=h((string)($mapping['status']??'not synced'))?></span></summary><form method="post" class="stack"><?=csrf_field()?><input type="hidden" name="op" value="update"><input type="hidden" name="promotion_id" value="<?=h((string)$p['public_id'])?>">
<div class="adminPackageFields"><label>Name<input name="name" value="<?=h((string)$p['name'])?>" required></label><label>Code<input name="code" value="<?=h((string)$p['code'])?>" required maxlength="40"></label><label>Status<select name="status"><option value="draft" <?=$p['status']==='draft'?'selected':''?>>Draft</option><option value="active" <?=$p['status']==='active'?'selected':''?>>Active</option><option value="archived" <?=$p['status']==='archived'?'selected':''?>>Archived</option></select></label><label>Discount type<select name="discount_type"><option value="percent" <?=$p['discount_type']==='percent'?'selected':''?>>Percent</option><option value="fixed_amount" <?=$p['discount_type']==='fixed_amount'?'selected':''?>>Fixed amount</option></select></label><label>Percent off<input name="percent_off" inputmode="decimal" value="<?=h($p['percent_basis_points']===null?'':number_format(((int)$p['percent_basis_points'])/100,2,'.',''))?>"></label><label>Fixed amount ($)<input name="amount_off_dollars" inputmode="decimal" value="<?=h($p['amount_off_cents']===null?'':number_format(((int)$p['amount_off_cents'])/100,2,'.',''))?>"></label><label>Duration<select name="duration"><option value="once" <?=$p['duration']==='once'?'selected':''?>>Once</option><option value="repeating" <?=$p['duration']==='repeating'?'selected':''?>>Repeating</option><option value="forever" <?=$p['duration']==='forever'?'selected':''?>>Forever</option></select></label><label>Repeating months<input name="duration_months" type="number" min="1" max="60" value="<?=h((string)($p['duration_months']??1))?>"></label><label>Customer scope<select name="customer_scope"><option value="all" <?=$p['customer_scope']==='all'?'selected':''?>>All customers</option><option value="new_customers" <?=$p['customer_scope']==='new_customers'?'selected':''?>>New customers</option><option value="existing_customers" <?=$p['customer_scope']==='existing_customers'?'selected':''?>>Existing customers</option></select></label><label>Minimum package ($)<input name="minimum_package_dollars" inputmode="decimal" value="<?=h($p['minimum_package_amount_cents']===null?'':number_format(((int)$p['minimum_package_amount_cents'])/100,2,'.',''))?>"></label><label>Starts<input type="datetime-local" name="starts_at" value="<?=h($dt($p['starts_at']))?>"></label><label>Ends<input type="datetime-local" name="ends_at" value="<?=h($dt($p['ends_at']))?>"></label><label>Global redemptions<input type="number" name="max_redemptions" min="1" value="<?=h($p['max_redemptions']===null?'':(string)$p['max_redemptions'])?>" placeholder="Unlimited"></label><label>Per-account limit<input type="number" name="per_account_limit" min="1" max="100" value="<?=h((string)$p['per_account_limit'])?>"></label></div><label>Description<textarea name="description" rows="2"><?=h((string)($p['description']??''))?></textarea></label><fieldset><legend>Eligible packages</legend><?php foreach($packages as $pkg):?><label><input type="checkbox" name="package_ids[]" value="<?=h((string)$pkg['public_id'])?>" <?=in_array((int)$pkg['id'],$eligible,true)?'checked':''?>> <?=h((string)$pkg['name'])?></label><?php endforeach?></fieldset><div class="inlineActions"><button>Save promotion</button></form><form method="post"><?=csrf_field()?><input type="hidden" name="op" value="sync"><input type="hidden" name="promotion_id" value="<?=h((string)$p['public_id'])?>"><button class="button secondary">Sync to Stripe</button></form></div><?php if($mapping&&$mapping['last_error']):?><div class="error"><?=h((string)$mapping['last_error'])?></div><?php endif?></details><?php endforeach?><?php if(!$promotions):?><p class="empty">No promotions created yet.</p><?php endif?></section>

<section class="adminBillingGrid"><article class="card"><span class="eyebrow">ACCOUNT CREDIT</span><h2>Adjust Stripe customer credit balance</h2><p>Credits reduce future invoices; debits increase future invoice amounts. Every adjustment is append-only and reversible by a new opposite transaction.</p><form method="post" class="stack"><?=csrf_field()?><input type="hidden" name="op" value="credit"><label>Account<select name="account_id" required><?php foreach($accounts as $a):?><option value="<?=h((string)$a['public_id'])?>"><?=h((string)$a['name'])?> · <?=h((string)$a['package_name'])?></option><?php endforeach?></select></label><label>Adjustment<select name="direction"><option value="credit">Credit customer</option><option value="debit">Debit customer</option></select></label><label>Amount ($)<input name="amount_dollars" inputmode="decimal" required placeholder="25.00"></label><label>Reason<input name="reason" maxlength="500" required></label><button>Apply adjustment</button></form></article><article class="card"><span class="eyebrow">POLICY</span><h2>V1.80 safeguards</h2><p>One promotion can be attached to a Checkout session. Local package/scope/date/redemption rules are evaluated before Stripe. A changed code cannot silently reuse an older Checkout session. Credits never rewrite invoices or AI usage; Stripe applies its immutable customer-balance ledger to future invoices.</p></article></section>

<section class="card"><div class="sectionHeadWeb"><div><span class="eyebrow">REDEMPTIONS</span><h2>Promotion lifecycle</h2></div></div><div class="tableWrap"><table><thead><tr><th>Promotion</th><th>Account</th><th>Package</th><th>Status</th><th>Discount recorded</th><th>Checkout</th><th>Subscription</th><th>When</th></tr></thead><tbody><?php foreach($redemptions as $r):?><tr><td><?=h((string)$r['code'])?> · <?=h((string)$r['promotion_name'])?></td><td><a href="/admin/account.php?id=<?=h(rawurlencode((string)$r['account_public_id']))?>"><?=h((string)$r['account_name'])?></a></td><td><?=h((string)$r['package_name'])?></td><td><?=h((string)$r['status'])?></td><td><?=h($money((int)$r['amount_discounted_cents']))?></td><td><code><?=h((string)($r['stripe_checkout_session_id']?:'—'))?></code></td><td><code><?=h((string)($r['stripe_subscription_id']?:'—'))?></code></td><td><?=h((string)($r['applied_at']?:$r['reserved_at']))?></td></tr><?php endforeach?><?php if(!$redemptions):?><tr><td colspan="8" class="empty">No promotion redemptions yet.</td></tr><?php endif?></tbody></table></div></section>

<section class="card"><div class="sectionHeadWeb"><div><span class="eyebrow">CREDIT LEDGER</span><h2>Customer balance adjustments</h2></div></div><div class="tableWrap"><table><thead><tr><th>Account</th><th>Type</th><th>Amount</th><th>Status</th><th>Stripe transaction</th><th>Reason</th><th>Operations</th></tr></thead><tbody><?php foreach($credits as $c):?><tr><td><?=h((string)$c['account_name'])?></td><td><?=h((string)$c['adjustment_type'])?></td><td><?=h(($c['amount_cents']<0?'-':'').$money(abs((int)$c['amount_cents'])))?></td><td><?=h((string)$c['status'])?></td><td><code><?=h((string)($c['stripe_balance_transaction_id']?:'—'))?></code><?php if($c['last_error']):?><div class="error"><?=h((string)$c['last_error'])?></div><?php endif?></td><td><?=h((string)$c['reason'])?></td><td><?php if($c['status']==='failed'):?><form method="post"><?=csrf_field()?><input type="hidden" name="op" value="retry_credit"><input type="hidden" name="adjustment_id" value="<?=h((string)$c['public_id'])?>"><button class="button secondary">Retry</button></form><?php elseif($c['status']==='applied'&&$c['adjustment_type']!=='reversal'):?><form method="post" class="stack"><?=csrf_field()?><input type="hidden" name="op" value="reverse_credit"><input type="hidden" name="adjustment_id" value="<?=h((string)$c['public_id'])?>"><input name="reason" maxlength="500" value="Reversal of prior adjustment." required><button class="button secondary">Reverse</button></form><?php endif?></td></tr><?php endforeach?><?php if(!$credits):?><tr><td colspan="7" class="empty">No credit adjustments yet.</td></tr><?php endif?></tbody></table></div></section>

<section class="card"><div class="sectionHeadWeb"><div><span class="eyebrow">INVOICE DISCOUNTS</span><h2>Gross → discount → net evidence</h2></div></div><div class="tableWrap"><table><thead><tr><th>Account</th><th>Promotion</th><th>Invoice</th><th>Gross subtotal</th><th>Discount</th><th>Net total</th><th>When</th></tr></thead><tbody><?php foreach($discounts as $d):?><tr><td><?=h((string)$d['account_name'])?></td><td><?=h((string)($d['code']?:'External/unknown'))?></td><td><code><?=h((string)$d['stripe_invoice_id'])?></code></td><td><?=h($money((int)$d['gross_subtotal_cents']))?></td><td><?=h($money((int)$d['discount_amount_cents']))?></td><td><?=h($money((int)$d['net_total_cents']))?></td><td><?=h((string)$d['created_at'])?></td></tr><?php endforeach?><?php if(!$discounts):?><tr><td colspan="7" class="empty">No invoice discount events recorded yet.</td></tr><?php endif?></tbody></table></div></section>
